from dataclasses import dataclass, field
from typing import Optional, Dict, Any

@dataclass
class SpeechSynthesisConfig:
    api_key: str
    region: str
    voice: str = "en-US-JennyNeural"
    output_format: str = "Audio16Khz32KBitRateMonoMp3"

@dataclass
class SynthesisRequest:
    text: Optional[str] = None
    ssml: Optional[str] = None
    config: Optional[Dict[str, Any]] = field(default_factory=dict)

@dataclass
class SynthesisResponse:
    audio_bytes: bytes
    content_type: str

import azure.cognitiveservices.speech as speechsdk
from speech_client import AzureSpeechClient
from speech_models import SynthesisRequest, SynthesisResponse, SpeechSynthesisConfig

def synthesize_ssml(payload: SynthesisRequest, config: SpeechSynthesisConfig) -> SynthesisResponse:
    speech_client = AzureSpeechClient(config)
    synthesizer = speech_client.get_synthesizer()

    result = synthesizer.speak_ssml_async(payload.ssml).get()

    if result.reason != speechsdk.ResultReason.SynthesizingAudioCompleted:
        raise RuntimeError(f"Azure speech synthesis failed: {result.cancellation_details.reason}")

    return SynthesisResponse(audio_bytes=result.audio_data, content_type='audio/mpeg')

from speech_client import AzureSpeechClient
from speech_models import SpeechSynthesisConfig
from typing import List, Dict, Any

def select_voice(config: SpeechSynthesisConfig, voice_name: str = None, locale: str = None) -> List[Dict[str, Any]]:
    speech_client = AzureSpeechClient(config)
    if voice_name:
        speech_client.select_voice(voice_name)
        return [{"message": f"Voice set to {voice_name}"}]
    elif locale:
        return speech_client.list_voices(locale=locale)
    else:
        # Default to listing en-US voices if no specific request
        return speech_client.list_voices(locale="en-US")

def save_audio(audio_bytes: bytes, file_path: str):
    try:
        with open(file_path, 'wb') as f:
            f.write(audio_bytes)
        return {"status": "success", "file_path": file_path}
    except Exception as e:
        return {"status": "error", "message": str(e)}
